/*
 * Hutchison Ports look and pages for the HPUK News or Other News site, from the browser.
 * GENERATED by tools/build_site_kit.py from branding/. Don't edit by hand.
 *
 * 1. Open the HPUK News or Other News site, signed in as a Site Owner.
 * 2. Press F12 (or Ctrl+Shift+I / Cmd+Option+I), open Console.
 * 3. Paste this whole file and press Enter. Chrome and Edge may first ask you
 *    to type "allow pasting".
 *
 * Safe to re-run: the theme, column formatting and diagrams are replaced,
 * navigation links are not duplicated, and pages that already exist are left
 * alone unless UPDATE_EXISTING below is true. That rewrites them from this
 * script, so edits made to them on the site are lost.
 */
(async () => {
  const THEME = {
    "name": "Hutchison Ports",
    "isInverted": false,
    "palette": {
      "themePrimary": "#002e6d",
      "themeLighterAlt": "#f5f7f9",
      "themeLighter": "#d9e0e9",
      "themeLight": "#b2c0d3",
      "themeTertiary": "#6682a7",
      "themeSecondary": "#1a437c",
      "themeDarkAlt": "#002962",
      "themeDark": "#002353",
      "themeDarker": "#001a3d",
      "neutralLighterAlt": "#f7f8fa",
      "neutralLighter": "#eef2f7",
      "neutralLight": "#e0e2e7",
      "neutralQuaternaryAlt": "#ccd0d6",
      "neutralQuaternary": "#babec8",
      "neutralTertiaryAlt": "#adb3be",
      "neutralTertiary": "#81899a",
      "neutralSecondary": "#56627a",
      "neutralPrimaryAlt": "#47546c",
      "neutralPrimary": "#33415c",
      "neutralDark": "#242e40",
      "black": "#171d29",
      "white": "#ffffff"
    }
  };
  const FORMATS = [
    {
      "list": "Site Pages",
      "field": "Status",
      "formatter": "{\n  \"$schema\": \"https://developer.microsoft.com/json-schemas/sp/v2/column-formatting.schema.json\",\n  \"elmType\": \"div\",\n  \"txtContent\": \"@currentField\",\n  \"style\": {\n    \"display\": \"=if(@currentField == '', 'none', 'inline-block')\",\n    \"box-sizing\": \"border-box\",\n    \"padding\": \"1px 10px\",\n    \"border-radius\": \"8px\",\n    \"font-size\": \"13px\",\n    \"line-height\": \"20px\",\n    \"white-space\": \"nowrap\",\n    \"background-color\": \"=if(indexOf('|Live|', '|' + @currentField + '|') >= 0, '#dcfce7', if(indexOf('|Expired|', '|' + @currentField + '|') >= 0, '#e0f2fe', '#eef2f7'))\",\n    \"color\": \"=if(indexOf('|Live|', '|' + @currentField + '|') >= 0, '#14532d', if(indexOf('|Expired|', '|' + @currentField + '|') >= 0, '#0c4a6e', '#33415c'))\",\n    \"border\": \"='1px solid ' + if(indexOf('|Live|', '|' + @currentField + '|') >= 0, '#15803d', if(indexOf('|Expired|', '|' + @currentField + '|') >= 0, '#0369a1', '#eef2f7'))\"\n  }\n}\n"
    },
    {
      "list": "Notices and Attachments",
      "field": "Status",
      "formatter": "{\n  \"$schema\": \"https://developer.microsoft.com/json-schemas/sp/v2/column-formatting.schema.json\",\n  \"elmType\": \"div\",\n  \"txtContent\": \"@currentField\",\n  \"style\": {\n    \"display\": \"=if(@currentField == '', 'none', 'inline-block')\",\n    \"box-sizing\": \"border-box\",\n    \"padding\": \"1px 10px\",\n    \"border-radius\": \"8px\",\n    \"font-size\": \"13px\",\n    \"line-height\": \"20px\",\n    \"white-space\": \"nowrap\",\n    \"background-color\": \"=if(indexOf('|Live|', '|' + @currentField + '|') >= 0, '#dcfce7', if(indexOf('|Expired|', '|' + @currentField + '|') >= 0, '#e0f2fe', '#eef2f7'))\",\n    \"color\": \"=if(indexOf('|Live|', '|' + @currentField + '|') >= 0, '#14532d', if(indexOf('|Expired|', '|' + @currentField + '|') >= 0, '#0c4a6e', '#33415c'))\",\n    \"border\": \"='1px solid ' + if(indexOf('|Live|', '|' + @currentField + '|') >= 0, '#15803d', if(indexOf('|Expired|', '|' + @currentField + '|') >= 0, '#0369a1', '#eef2f7'))\"\n  }\n}\n"
    },
    {
      "list": "Delivery Log",
      "field": "DeliveryStatus",
      "formatter": "{\n  \"$schema\": \"https://developer.microsoft.com/json-schemas/sp/v2/column-formatting.schema.json\",\n  \"elmType\": \"div\",\n  \"txtContent\": \"@currentField\",\n  \"style\": {\n    \"display\": \"=if(@currentField == '', 'none', 'inline-block')\",\n    \"box-sizing\": \"border-box\",\n    \"padding\": \"1px 10px\",\n    \"border-radius\": \"8px\",\n    \"font-size\": \"13px\",\n    \"line-height\": \"20px\",\n    \"white-space\": \"nowrap\",\n    \"background-color\": \"=if(indexOf('|Sent|', '|' + @currentField + '|') >= 0, '#dcfce7', if(indexOf('|Failed|Skipped - not an urgent publisher|Skipped - no destinations|', '|' + @currentField + '|') >= 0, '#fee2e2', if(indexOf('|Reconcile|Skipped - audience targeted|', '|' + @currentField + '|') >= 0, '#e0f2fe', '#eef2f7')))\",\n    \"color\": \"=if(indexOf('|Sent|', '|' + @currentField + '|') >= 0, '#14532d', if(indexOf('|Failed|Skipped - not an urgent publisher|Skipped - no destinations|', '|' + @currentField + '|') >= 0, '#7f1d1d', if(indexOf('|Reconcile|Skipped - audience targeted|', '|' + @currentField + '|') >= 0, '#0c4a6e', '#33415c')))\",\n    \"border\": \"='1px solid ' + if(indexOf('|Sent|', '|' + @currentField + '|') >= 0, '#15803d', if(indexOf('|Failed|Skipped - not an urgent publisher|Skipped - no destinations|', '|' + @currentField + '|') >= 0, '#b91c1c', if(indexOf('|Reconcile|Skipped - audience targeted|', '|' + @currentField + '|') >= 0, '#0369a1', '#eef2f7')))\"\n  }\n}\n"
    }
  ];
  const PAGES = [
    {
      "name": "Publisher-Guide",
      "title": "Publisher Guide",
      "nav": null,
      "summary": "How to publish news and notices, and what happens after you publish.",
      "sections": [
        {
          "image": "news-workflow.png",
          "alt": "Swimlane diagram of SharePoint News: a publisher publishes a post; flow C3 checks urgent posts and sends email and Teams alerts per port; flow C2 sends the Monday roundup; flow C1 expires posts daily; every send is recorded in the Delivery Log and failures go to the Communications shared mailbox.",
          "caption": "How news reaches people: publishing, urgent notices, the Monday roundup and expiry."
        },
        "<h2>Before you publish</h2>\n<p>Every news post follows the same reading order: a clear title, a short summary that says who is affected, the main content under descriptive headings, any action required with its deadline, attachment links, and a named business contact.</p>\n<ol>\n<li>Create the post from the <strong>HPUK News post</strong> template (Other News: <strong>Other News post</strong>).</li>\n<li>Write the summary in the page <strong>Description</strong>. It is what readers see in news views, emails and Teams.</li>\n<li>Upload attachments to <strong>Notices and Attachments</strong> and link to them. Do not attach files to the page itself.</li>\n<li>Fill in the page details (Page details, top right):\n<ul>\n<li><strong>Department</strong> and <strong>Category</strong>: required. Department is who <em>owns</em> the message (not who publishes it); Category is what it is about. Choose one of each. Use Category <em>Health and Safety</em> for anything that belongs in the Safety section. Put the location in Port and urgency in Urgent, not in Department or Category. If nothing fits, ask Communications to add a term; use <em>General Information</em> only as a last resort.</li>\n<li><strong>Strategy theme</strong>: optional. Choose which part of our strategy the story supports: <em>Our People</em>, <em>Our Business</em>, <em>Our Environment</em> or <em>One TEAM</em>. You can choose more than one, or none for routine notices.</li>\n<li><strong>Port</strong>: required. Choose the ports affected, or <em>All ports</em>. There is no blank option, so a notice is never sent everywhere by accident.</li>\n<li><strong>Expiry date</strong>: the last day the notice is current. It leaves the news views the next morning. Leave blank for news that does not expire.</li>\n<li><strong>Include in weekly roundup</strong>: on by default. Turn off for posts that should not go in Monday's port digest.</li>\n<li><strong>Urgent</strong>: only for notices that must reach people now. Only Chloe, Rachel and Toby can send urgent notices: when they publish the post, it goes straight out by email and Teams to every port chosen. If anyone else marks a post Urgent, nothing is sent and Communications is told. The alert reaches licensed staff only: staff without a Microsoft licence get urgent notices through their own area's route, so tell the area as well.</li>\n</ul></li>\n<li>If the post is only for a group (for example managers), set <strong>Audience</strong>. Audience-targeted posts are never emailed to whole ports; Communications is told so it can send to the right group.</li>\n<li>Select <strong>Publish</strong> (or <strong>Post news</strong>). There is no approval step: publishers are pre-approved, so the post is live as soon as you publish it. Check it carefully first, especially an urgent post, because the alert goes out straight away. If you scheduled it, it goes live at the scheduled time.</li>\n</ol>",
        "<h2>Images and video</h2>\n<ul>\n<li><strong>Main image</strong>: select <strong>Add image</strong> at the top of the post. It is also the thumbnail on HPUK News and the intranet home, so choose a clear, wide (16:9) picture.</li>\n<li><strong>More pictures</strong>: use the <strong>Image</strong> web part, or <strong>Image gallery</strong> for several.</li>\n<li><strong>Alt text on every image</strong>: describe what the picture shows for people using screen readers. Don't put words inside an image; put them in the post.</li>\n<li><strong>Video</strong>: upload the MP4 to the <strong>News Videos</strong> library on your site, then add it to the post with the <strong>File and media</strong> web part. Don't embed YouTube or other outside video.</li>\n<li><strong>Captions</strong>: open the video, check the captions or transcript Stream creates, correct them, then set <strong>Captions checked</strong> to Yes in the library.</li>\n<li>Follow the brand guidelines (V6) for imagery and colour.</li>\n<li>Emails, Teams alerts and the Monday roundup show the title, summary and a link only. Readers open the post to see pictures and video.</li>\n</ul>",
        "<h2>Urgent notices</h2>\n<p>An urgent alert goes out once per port and channel. Editing and republishing the post afterwards does not send it again.</p>\n<p>To send a correction as a new alert: set <strong>Notification round</strong> up by one, set <strong>Urgent alert sent</strong> back to <em>No</em>, and republish. Only Communications should do this.</p>\n<p>A sent alert is not a read receipt. Email and Teams delivery does not prove that a colleague has read a notice.</p>",
        "<h2>Expiry and withdrawal</h2>\n<p>Expiry only removes a post from the current news views. It does not delete the page or its attachments, and anyone with the link can still open it. To withdraw a notice that must not be read, unpublish it and contact Communications.</p>\n<p>All news content is kept for 7 years, including deleted pages and files.</p>",
        "<h2>Help</h2>\n<p>For publishing questions, contact Communications. If an alert or roundup did not arrive, email the Communications shared mailbox. Every delivery is recorded in the Delivery Log.</p>"
      ]
    }
  ];
  const IMAGES = {"news-workflow.png": {"width": 4000, "height": 2184, "data": ""}};
  const UPDATE_EXISTING = false;
  const IMAGE_WP = "d1d91016-032f-456d-98a4-721247c305e8"; // SharePoint Image web part

  const site = (location.pathname.match(/^\/(sites|teams)\/[^/]+/i) || [""])[0];
  const web = location.origin + site;
  const H = { Accept: "application/json;odata=verbose", "Content-Type": "application/json;odata=verbose" };
  const q = (s) => s.replace(/'/g, "''");
  const results = [];
  const log = (step, ok, detail = "") => {
    results.push({ step, result: ok ? "OK" : "FAILED", detail });
    console[ok ? "log" : "warn"](`${ok ? "OK    " : "FAILED"} ${step}${detail ? " - " + detail : ""}`);
  };

  const ctx = await fetch(web + "/_api/contextinfo", { method: "POST", headers: H, credentials: "include" });
  if (!ctx.ok) { console.error(`Can't reach ${web}/_api (HTTP ${ctx.status}). Open the site first.`); return; }
  const digest = (await ctx.json()).d.GetContextWebInformation.FormDigestValue;

  async function sp(path, body, extraHeaders = {}, method = body === undefined ? "GET" : "POST") {
    const r = await fetch(web + path, {
      method, credentials: "include",
      headers: { ...H, "X-RequestDigest": digest, ...extraHeaders },
      body: body === undefined || body === null ? undefined : JSON.stringify(body),
    });
    if (!r.ok) throw new Error(`HTTP ${r.status}: ${(await r.text()).slice(0, 240)}`);
    const t = await r.text();
    return t ? JSON.parse(t).d : null;
  }
  const exists = async (path) => (await fetch(web + path, { headers: H, credentials: "include" })).ok;

  console.log(`Setting up ${web}`);

  // 1. Theme
  try {
    await sp("/_api/ThemeManager/ApplyTheme", {
      name: THEME.name,
      themeJson: JSON.stringify({ palette: THEME.palette, isInverted: THEME.isInverted }),
    });
    log(`Theme '${THEME.name}'`, true);
  } catch (e) { log(`Theme '${THEME.name}'`, false, e.message); }

  // 2. Status column formatting, and each list's URL for page links
  const listUrls = {};
  for (const f of FORMATS) {
    try {
      const l = await sp(`/_api/web/lists/getbytitle('${q(f.list)}')/RootFolder?$select=ServerRelativeUrl`);
      listUrls[f.list] = l.ServerRelativeUrl;
      await sp(`/_api/web/lists/getbytitle('${q(f.list)}')/fields/getbyinternalnameortitle('${q(f.field)}')`,
        { __metadata: { type: "SP.FieldChoice" }, CustomFormatter: f.formatter },
        { "X-HTTP-Method": "MERGE", "IF-MATCH": "*" });
      log(`Format ${f.list} / ${f.field}`, true);
    } catch (e) { log(`Format ${f.list} / ${f.field}`, false, e.message); }
  }

  // 3. Diagrams into Site Assets
  const imageInfo = {};
  if (Object.keys(IMAGES).length) {
    try {
      const lib = await sp("/_api/web/lists/EnsureSiteAssetsLibrary", null);
      const folder = (await sp(`/_api/web/lists(guid'${lib.Id}')/RootFolder?$select=ServerRelativeUrl`)).ServerRelativeUrl;
      const siteId = (await sp("/_api/site?$select=Id")).Id;
      const webId = (await sp("/_api/web?$select=Id")).Id;
      for (const [name, img] of Object.entries(IMAGES)) {
        const bytes = Uint8Array.from(atob(img.data), (c) => c.charCodeAt(0));
        const r = await fetch(`${web}/_api/web/GetFolderByServerRelativeUrl('${q(folder)}')/Files/add(url='${q(name)}',overwrite=true)`, {
          method: "POST", credentials: "include", headers: { Accept: H.Accept, "X-RequestDigest": digest }, body: bytes,
        });
        if (!r.ok) throw new Error(`HTTP ${r.status} uploading ${name}: ${(await r.text()).slice(0, 200)}`);
        const f = (await r.json()).d;
        imageInfo[name] = { url: f.ServerRelativeUrl, uniqueId: f.UniqueId, listId: lib.Id, siteId, webId, width: img.width, height: img.height };
        log(`Upload ${name}`, true, f.ServerRelativeUrl);
      }
    } catch (e) { log("Upload diagrams", false, e.message); }
  }

  // 4. Pages
  const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const fill = (h) => h.replace(/\{\{(list|new):([^}|]+)(?:\|([^}]+))?\}\}/g, (_, kind, title, label) => {
    const url = listUrls[title];
    const text = esc(label || title);
    if (!url) return text;
    return `<a href="${url}${kind === "new" ? "/NewForm.aspx" : ""}">${text}</a>`;
  });
  // A string section is a text web part; an {image, alt, caption} section is an
  // Image web part (select it to open full size) with its caption below.
  const parts = (sections) => sections.flatMap((s) => {
    if (typeof s === "string") return [{ html: fill(s) }];
    const img = imageInfo[s.image];
    if (!img) return [{ html: `<p><em>${esc(s.caption)}</em> (diagram ${esc(s.image)} was not uploaded)</p>` }];
    return [{ section: s, img }, { html: `<p><em>${esc(s.caption)}</em> <a href="${img.url}">Open the diagram full size</a></p>` }];
  });
  const control = (part, i) => {
    const id = crypto.randomUUID();
    const position = { zoneIndex: i + 1, sectionIndex: 1, sectionFactor: 12, layoutIndex: 1, controlIndex: 1 };
    if (part.html) return { controlType: 4, id, position, emphasis: {}, editorType: "CKEditor", innerHTML: part.html };
    const { section: s, img } = part;
    return {
      controlType: 3, id, position, emphasis: {}, webPartId: IMAGE_WP,
      webPartData: {
        id: IMAGE_WP, instanceId: id, title: "Image", description: s.alt, dataVersion: "1.9",
        serverProcessedContent: { htmlStrings: {}, searchablePlainTexts: { captionText: "" }, imageSources: { imageSource: img.url }, links: { linkUrl: img.url } },
        properties: {
          imageSourceType: 2, altText: s.alt, captionText: "", overlayText: "", linkUrl: img.url, fileName: s.image,
          siteId: img.siteId, webId: img.webId, listId: img.listId, uniqueId: img.uniqueId,
          imgWidth: img.width, imgHeight: img.height, alignment: "Center", fixAspectRatio: false,
        },
      },
    };
  };
  const canvas = (sections) => JSON.stringify([
    ...parts(sections).map(control),
    { controlType: 0, pageSettingsSlice: { isDefaultDescription: true, isDefaultThumbnail: true } },
  ]);
  const META = { __metadata: { type: "SP.Publishing.SitePage" } };

  for (const p of PAGES) {
    const url = `${site}/SitePages/${p.name}.aspx`;
    const fileApi = `/_api/web/GetFileByServerRelativeUrl('${q(url)}')`;
    if (await exists(`${fileApi}?$select=Name`)) {
      if (!UPDATE_EXISTING) {
        log(`Page ${p.name}.aspx`, true, "already exists, left as it is (UPDATE_EXISTING = true refreshes it)");
        continue;
      }
      try {
        const id = (await sp(`${fileApi}/ListItemAllFields?$select=Id`)).Id;
        try { await sp(`/_api/sitepages/pages(${id})/checkoutpage`, null); } catch (_) { /* already checked out to you */ }
        await sp(`/_api/sitepages/pages(${id})/savepage`, { ...META, Title: p.title, Description: p.summary, CanvasContent1: canvas(p.sections) }, { "IF-MATCH": "*" });
        await sp(`/_api/sitepages/pages(${id})/publish`, null);
        log(`Page ${p.name}.aspx`, true, "updated and published");
      } catch (e) { log(`Page ${p.name}.aspx`, false, e.message); }
      continue;
    }
    try {
      const page = await sp("/_api/sitepages/pages", { ...META, PageLayoutType: "Article" });
      const id = page.Id;
      try { await sp(`/_api/sitepages/pages(${id})/checkoutpage`, null); } catch (_) { /* new pages start checked out */ }
      await sp(`/_api/sitepages/pages(${id})/savepage`, { ...META, Title: p.title, Description: p.summary, CanvasContent1: canvas(p.sections) }, { "IF-MATCH": "*" });
      try {
        await sp(`/_api/web/GetFileByServerRelativeUrl('${q(site + "/" + page.Url)}')/ListItemAllFields/ValidateUpdateListItem`, {
          formValues: [{ __metadata: { type: "SP.ListItemFormUpdateValue" }, FieldName: "FileLeafRef", FieldValue: p.name }],
          bNewDocumentUpdate: false,
        });
      } catch (e) { log(`Rename ${page.Url} to ${p.name}.aspx`, false, e.message + " (links between pages will need fixing)"); }
      await sp(`/_api/sitepages/pages(${id})/publish`, null);
      log(`Page ${p.name}.aspx`, true, "created and published");
    } catch (e) { log(`Page ${p.name}.aspx`, false, e.message); }
  }

  // 5. Left-hand navigation
  try {
    const nav = await sp("/_api/web/navigation/QuickLaunch?$select=Title");
    const have = new Set(nav.results.map((n) => n.Title));
    for (const p of PAGES) {
      if (!p.nav || have.has(p.nav)) continue;
      await sp("/_api/web/navigation/QuickLaunch", { __metadata: { type: "SP.NavigationNode" }, Title: p.nav, Url: `${site}/SitePages/${p.name}.aspx` });
    }
    log("Navigation links", true);
  } catch (e) { log("Navigation links", false, e.message); }

  console.table(results);
  console.log("Done. Reload the page to see the theme.");
})();
